from pathlib import Path
p=Path('/workspace/superset/apps/desktop/src/main/lib/ssh-direct/workstation-browser-cdp-channel.test.ts');p.write_text('''import {expect,test} from "bun:test";
import type {BrowserCdpPacket} from "@superset/shared/browser-cdp-bridge";
import {WorkstationBrowserCdpChannel} from "./workstation-browser-cdp-channel";
function fixture(){const packets:BrowserCdpPacket[]=[],sessions:Array<{sent:string[],releases:number,callbacks:{onMessage:(raw:string)=>void,onDetach:(reason:string)=>void}}>=[];let current=true,invalidations=0,failure:Error|undefined,sendFailure=false,duringOpen:((callbacks:{onMessage:(raw:string)=>void,onDetach:(reason:string)=>void})=>void)|undefined;const busy=Error("original busy");const channel=new WorkstationBrowserCdpChannel({current:()=>current,invalidate:()=>{invalidations++;current=false;},send:p=>{if(sendFailure)throw Error("socket closed");packets.push(p);},isBusy:error=>error===busy,pin:input=>{if(input.workspaceId!=="workspace"||input.paneId!=="pane")throw Error("foreign pane");if(failure)throw failure;let captured:typeof sessions[number]|undefined;return{release:()=>{if(captured)captured.releases++;},open:callbacks=>{captured={sent:[],releases:0,callbacks};sessions.push(captured);duringOpen?.(callbacks);return{send:raw=>captured?.sent.push(raw),detach:()=>{throw Error("Must release the pinned handle only");}};}};}});const open=(extra:Record<string,unknown>={})=>{const input={type:"cdp-open" as const,sessionId:crypto.randomUUID(),workspaceId:"workspace",paneId:"pane",...extra};channel.receive(input as never);return input;};return{channel,packets,sessions,busy,open,retire:()=>{current=false;},invalidations:()=>invalidations,setFailure:(e:Error)=>{failure=e;},failSend:()=>{sendFailure=true;},duringOpen:(fn:typeof duringOpen)=>{duringOpen=fn;}};}
test("the Main CDP channel acknowledges an actual pin and keeps original raw frames",()=>{const f=fixture(),p=f.open();expect(f.packets).toEqual([{type:"cdp-open-result",sessionId:p.sessionId,ok:true}]);const raw=' {"id":1,"method":"Target.getTargets"} ';f.channel.receive({type:"cdp-input",sessionId:p.sessionId,raw});expect(f.sessions[0]?.sent).toEqual([raw]);f.sessions[0]?.callbacks.onMessage('{"id":1,"result":{}}');expect(f.packets.at(-1)).toEqual({type:"cdp-output",sessionId:p.sessionId,raw:'{"id":1,"result":{}}'});f.channel.receive({type:"cdp-close",sessionId:p.sessionId,code:1000});expect(f.sessions[0]?.releases).toBe(1);f.channel.closeAll();expect(f.sessions[0]?.releases).toBe(1);});
test("original debugger events emitted during attach reach only their captured session before the ack",()=>{const f=fixture();f.duringOpen(c=>c.onMessage("early original event"));const p=f.open();expect(f.packets).toEqual([{type:"cdp-output",sessionId:p.sessionId,raw:"early original event"},{type:"cdp-open-result",sessionId:p.sessionId,ok:true}]);});
test("busy and invalid panes return scoped failure without disturbing an existing session",()=>{const f=fixture();f.open();f.setFailure(f.busy);const p=f.open();expect(f.packets.at(-1)).toEqual({type:"cdp-open-result",sessionId:p.sessionId,ok:false,code:1013});const q=f.open({workspaceId:"foreign"});expect(f.packets.at(-1)).toEqual({type:"cdp-open-result",sessionId:q.sessionId,ok:false,code:1011});expect(f.sessions[0]?.releases).toBe(0);f.channel.closeAll();expect(f.sessions[0]?.releases).toBe(1);});
test("late native events and old closes cannot release a new CDP pin",()=>{const f=fixture(),p=f.open(),old=f.sessions[0];old?.callbacks.onDetach("target closed");expect(f.packets.at(-1)).toEqual({type:"cdp-close",sessionId:p.sessionId,code:1011});f.open();f.channel.receive({type:"cdp-close",sessionId:p.sessionId,code:1000});old?.callbacks.onMessage("late event");expect(f.sessions[0]?.releases).toBe(1);expect(f.sessions[1]?.releases).toBe(0);expect(f.packets.some(p=>p.type==="cdp-output"&&p.raw==="late event")).toBe(false);});
test("retired owner scope cannot dispatch commands or deliver responses",()=>{for(const direction of ["input","output"]){const f=fixture(),p=f.open();f.retire();if(direction==="input")f.channel.receive({type:"cdp-input",sessionId:p.sessionId,raw:"stale"});else f.sessions[0]?.callbacks.onMessage("stale");expect(f.sessions[0]?.sent).toEqual([]);expect(f.sessions[0]?.releases).toBe(1);expect(f.packets).toHaveLength(1);expect(f.invalidations()).toBe(1);}});
test("close during synchronous attach withholds its late acknowledgement and releases the returned pin",()=>{const f=fixture();f.duringOpen(c=>c.onDetach("closed during attach"));const p=f.open();expect(f.packets).toEqual([{type:"cdp-close",sessionId:p.sessionId,code:1011}]);expect(f.sessions[0]?.releases).toBe(1);});
test("a failed bridge send closes all exact pins without throwing from native callbacks",()=>{const f=fixture();f.open();f.open();f.failSend();expect(()=>f.sessions[0]?.callbacks.onMessage("event")).not.toThrow();expect(f.sessions.map(s=>s.releases)).toEqual([1,1]);expect(f.invalidations()).toBe(1);});
test("duplicate session ids and wrong-direction frames are rejected instead of rebinding",()=>{const f=fixture(),p=f.open();expect(()=>f.channel.receive(p)).toThrow();expect(()=>f.channel.receive({type:"cdp-output",sessionId:p.sessionId,raw:"wrong direction"})).toThrow();expect(f.sessions).toHaveLength(1);f.channel.closeAll();expect(f.sessions[0]?.releases).toBe(1);});
test("Main keeps the original input limit while allowing larger screenshot responses",()=>{const f=fixture(),p=f.open(),raw="x".repeat(4*1024*1024+1);f.sessions[0]?.callbacks.onMessage(raw);expect(f.packets.at(-1)?.type).toBe("cdp-output");f.channel.receive({type:"cdp-input",sessionId:p.sessionId,raw});expect(f.sessions[0]?.sent).toEqual([]);expect(f.sessions[0]?.releases).toBe(1);expect(f.packets.at(-1)).toEqual({type:"cdp-close",sessionId:p.sessionId,code:1009});});
''')
